.control
* Run DC sweep matching Baker Figure 22.17
dc VC 500m 700m 2m
meas dc vout_at_500m find v(vout) at=500m
meas dc vout_at_700m find v(vout) at=700m
let delta_vout = abs(vout_at_700m - vout_at_500m)
print delta_vout

* Run DC Operating Point
op
let vout_dc_val = v(vout)
print vout_dc_val
let pwr = -i(vdd) * 1.8
print pwr

* Run AC common-mode analysis
alter VC = 0.6 ac 1
ac dec 10 1 100Meg
let cm_gain_db = vdb(vout)
meas ac ac_cm_dc find cm_gain_db at=1

* Run wide DC sweep to identify common-mode input range
dc VC 0.0 1.8 0.01
meas dc vcm_max_meas when v(vout)=1.65 fall=1

quit
.endc
.end

